###deimos_expertmode
# @name: [P1 Only + Scale] Big Salgio (BOSS) - All Schools Ranks 3-7 Spellements - Celestia - The Chancel (Sigil)
# @zone: Celestia/CL_Hub
# @author: Discord: homeyo / Github: zerosenses
# @format: expertmode
# @clients: ==1
# @description: Excellent bot for Big Salgio / All Schools Ranks 3-7 Spellements.

#DIALOGUE & COMBAT (ENABLED).
#START ANYWHERE.
#P1 ONLY.
#DORM EQUIPPED.
#ALLOW ENDORSEMENTS (NO).
#DISABLE ANTI-AFK (DEIMOS SETTING).
#START WITHOUT ANY ELIXIRS ACTIVE; OR ONLY THE ELIXIR-LV-60 ACTIVE.

#SET "SCALE" TO "False" TO NOT USE THE SCALES OF KNOWLEDGE.
#SET "POTIONS" TO "False" TO SAVE GOLD. 
#WHEN POTIONS IS SET TO "True", AND GOLD FALLS BELOW 10%; TRIGGERS A FALLBACK TO NATURAL HEALING (AS IF SET TO "False").










setvar SCALE = True
setvar POTIONS = False










block potion {

#USE POTION
if p1 potioncountabove 0 {
 until not p1 healthbelow 80% AND not p1 manabelow 25% {
            p1 clickwindow ['WorldView', 'windowHUD', 'btnPotions']
 }
}



#REFILL
if p1 potioncountbelow 1 {



 #MARK
 until p1 windowdisabled ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'RecallButton'] {
        p1 clickwindow ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'MarkButton']
         sleep 2
 }

 until not p1 windowdisabled ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'RecallButton'] {
            p1 clickwindow ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'MarkButton']
             sleep 2
 }





 #GO TO COMMONS
 until p1 inzone WizardCity/WC_Hub {
                                     until p1 inzone WizardCity/Interiors/WC_Housing_Dorm_Interior {
                                                                                                     p1 clickwindow ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'GotoDormButton']
                                                                                                   }

 until p1 inzone WizardCity/WC_Ravenwood {
                                                p1 tp XYZ(-203.839, 4.139, 0.000)
                                         }

 until p1 inzone WizardCity/WC_Hub {
                                     p1 tp XYZ(14.533, -2207.150, -156.894)
                                   }
 }




 #HILDA BREWER
 until p1 hasxyz XYZ(-4530.453, 561.836, 229.000) {
                                                    p1 tp XYZ(-4530.453, 561.836, 229.000)
                                                  }

 until p1 windowvisible ['WorldView', 'main', 'fillallpotions'] {
                                                                  p1 sendkey X, .05
                                                                }

 while p1 windowvisible ['WorldView', 'main', 'fillallpotions'] {
  #REFILL ALL POTIONS
  p1 clickwindow ['WorldView', 'main', 'fillallpotions']

  #BUY
  p1 clickwindow ['WorldView', 'main', 'buyAction']

  #CLOSE
  p1 clickwindow ['WorldView', 'main', 'exit']
 }



 #RECALL
 if p1 windowdisabled ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'RecallButton'] {
  until not p1 windowdisabled ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'RecallButton'] {
                                                                                                          sleep .01
  }
 }

 until p1 windowdisabled ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'RecallButton'] {
        p1 clickwindow ['WorldView', 'windowHUD', 'compassAndTeleporterButtons', 'RecallButton']
 }

}

}










